<template>
	<view class="oederPay">

		<view class="list">
			<view class="item" v-for="item in orderInfo.itemList" :key="item.courseId">
				<view class="item-titbox">
					<text class="item-type" :class="item.bg">{{item.subjectName}}</text>
					<!-- <text class="item-type shuxue">数学</text> -->
					<!-- <text class="item-type yuwen">语文</text> -->
					<!-- <text class="item-type wuli">物理</text> -->
					<text class="item-title">{{item.courseTitle}}</text>
				</view>
				<view class="item-time ovHide">{{item.desc}}</view>
				<view class="item-address">
					<text class="iconfont icon-touzijigou"></text>
					<text class="adres-tex ovHide">{{item.placeName}}</text>
				</view>
				<view class="item-address">
					<text class="iconfont icon-fenxiangsheding-dizhi"></text>
					<text class="adres-tex ovHide">{{item.campusAddress}}</text>
				</view>
				<view class="item-flex">
					<view class="item-name">
						<text class="iconfont icon-navicon-grkh"></text>{{item.teacherName}}
					</view>
				</view>
				<view class="line"></view>
				<view class="item-end">
					<view class="end-left">
						<view class="end-is">共{{item.sessionCount}}次课</view>
						<!-- <view class="end-num">共8次课</view> -->
					</view>
					<view class="end-right">
						<view class="end-money">
							<text class="danwei">¥</text>
							<text class="price">{{item.price}}</text>
						</view>
					</view>
				</view>
			</view>
		</view>

		<!-- 大纲 -->
		<view class="teacher-box">
			<view class="teacher-title">
				<text></text>费用明细
			</view>
			<view class="grade-list">
				<view class="grade-cont">
					<view class="grade-tex">课程总数</view>
					<text class="grade-num">{{orderInfo.itemList.length}}个</text>
					<!-- <text class="iconfont icon-right none"></text> -->
				</view>
				<view class="grade-cont">
					<view class="grade-tex">课程费用</view>
					<text class="grade-num">¥{{orderInfo.payAmount}}</text>
				</view>
				<view class="grade-cont" @click="open">
					<view class="grade-tex">优惠券</view>
					<text class="grade-num red">
						<text v-if="quanMoney">- ¥{{quanMoney}}</text>
					</text>
					<text class="iconfont icon-right "></text>
				</view>
				<view class="grade-cont">
					<view class="grade-tex">应付金额</view>
					<text class="grade-num">¥{{payMoney}}</text>
				</view>
			</view>
		</view>

		<!-- 温馨提示 -->
		<view class="tips">
			<view class="iconfont icon--zhuyi"></view>
			<view class="tips-tex">
				温馨提示：支付成功后，管理员将在1个工作日内为您分配
				会课学习账号，届时请留意短信通知。
			</view>
		</view>


		<!-- 添加选课单 -->
		<view class="add-box" :style="{paddingBottom: paddingbottom + 'rpx'}">
			<view class="xieyi">
				<text class="checkbox" :class="{active : checkboxBool}" @click="checkboxBool = !checkboxBool">
					<text class="iconfont icon-duigou" v-if="checkboxBool"></text>
				</text>
				<text class="xieyi-tex">我已阅读并同意</text>
				<text class="xieyi-book" @click="openxieyi">《课程报名协议》</text>
			</view>
			<view class="add-end">
				<view class="price-box">
					<view class="price-num">
						<text class="heji">合计</text>
						<text class="danwei">¥</text>
						<text class="price">{{payMoney}}</text>
					</view>
				</view>
				<view class="add-btn" @click="pay()">微信支付</view>
			</view>
		</view>

		<!-- 优惠券列表 -->
		<uni-popup ref="popup" background-color="#fff" border-radius="10px 10px 0 0">
			<view class="popup-content">
				<view class="canshu-title">
					<view class="tit">
						优惠券
					</view>
					<text class="iconfont icon-guanbi3" @click="close"></text>
				</view>
				<view class="canshu-content">
					<view class="canshu-detail">
						<view class="quan-list">
							<view class="account-item" v-for="item in quanList" :key="item.couponId"
								:class="{active:quanId == item.couponId}" @click="quanChange(item)">
								<image src="/static/images/youhuijuan.jpg"></image>
								<view class="account-tex">
									<view class="account-label">
										<text>¥</text>{{item.couponValue}}
									</view>
									<view class="account-value">{{item.endTime}}前可用</view>
								</view>
							</view>
						</view>
					</view>
				</view>
			</view>
		</uni-popup>

		<!-- 协议 -->
		<uni-popup ref="xieyi" background-color="#fff" border-radius="10px 10px 0 0">
			<view class="popup-content">
				<view class="canshu-title">
					<view class="tit">
						温馨提示
					</view>
					<text class="iconfont icon-guanbi3" @click="closexieyi"></text>
				</view>
				<view class="canshu-content">
					<view class="canshu-detail">
						<view class="xieyicontent">
							<rich-text :nodes="xieyi"></rich-text>
						</view>
					</view>
				</view>
			</view>
		</uni-popup>

	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo,
		minus
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		createOrder,
		queryAvailableCoupons,
		queryOrderDetail,
		getUserAgreement
	} from '@/api/index.js'

	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				checkboxBool: false,
				orderId: '',
				xieyi: '',
				quanList: [],
				orderInfo: {
					itemList: []
				},
				payMoney: 0,
				quanMoney: 0,
				quanId: '',
			};
		},
		computed: {

			paddingbottom() {
				const res = wx.getSystemInfoSync()
				const {
					screenHeight,
					safeArea: {
						bottom
					}
				} = res
				if (screenHeight && bottom) {
					let safeBottom = screenHeight - bottom
					return safeBottom
				} else {
					return 0
				}
			}
		},
		components: {

		},
		onLoad(options) {
			this.orderId = options.orderId
			this.init()
		},
		mounted() {

		},
		created() {
			this.getxieyi()
		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			async init() {
				let _data = await queryOrderDetail(this.orderId);
				if (_data.code == 200) {
					this.orderInfo = _data.data
					this.getYhq(false)
				}
			},


			async getYhq(type) {
				let courseIds = []
				this.orderInfo.itemList.map(item => {
					courseIds.push(item.courseId)
				})
				let _res = await queryAvailableCoupons(courseIds.join(','));
				if (_res.code == 200) {
					if (_res.data.length) {
						this.quanList = _res.data
						this.quanMoney = this.quanList[0].couponValue
						this.quanId = this.quanList[0].couponId
						this.payMoney = minus(this.orderInfo.payAmount, this.quanMoney)
					} else {
						this.quanList = _res.data
						this.quanMoney = ''
						this.quanId = ''
						this.payMoney = this.orderInfo.payAmount
					}
				}
				if (this.quanList.length > 0 && type) {
					this.$refs.popup.open('bottom')
				}
				if (this.quanList.length == 0 && type) {
					toast('暂无优惠券...')
				}
			},

			async getxieyi() {
				let _data = await getUserAgreement();
				if (_data.code == 200) {
					this.xieyi = _data.data.content
				}
			},

			pay() {
				if (!this.checkboxBool) return toast('请阅读并同意课程报名协议')
				const param = {
					orderSn: this.orderInfo.orderId,
					couponId: this.quanId,
					payAmount: this.payMoney,
					productName: '智慧学堂',
				}
				toast('支付功能正在完善...')
				// jweixin.miniProgram.redirectTo({
				// 	url: `/subpackage/lesson-pay/lesson-pay?orderInfo=${JSON.stringify(param)}`
				// });
			},

			quanChange(item) {
				if (this.quanId == item.couponId) {
					this.quanMoney = ''
					this.quanId = ''
					this.payMoney = this.orderInfo.payAmount
				} else {
					this.quanMoney = item.couponValue
					this.quanId = item.couponId
					this.payMoney = minus(Number(this.orderInfo.payAmount), Number(this.quanMoney))
				}
				this.close()
			},

			open() {
				this.getYhq(true)
			},
			openxieyi() {
				this.$refs.xieyi.open('bottom')
			},

			close() {
				this.$refs.popup.close()
			},
			closexieyi() {
				this.$refs.xieyi.close()
			},

			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

